"""Exact certificate: S5-stabilizer spectrum on GL_5(F_2).

All computations use Python's integers and exhaustive finite enumeration.
Run: python3 verify.py
"""
from collections import Counter
from itertools import permutations
from math import prod

N = 5
PERMS = list(permutations(range(N)))
INDEX = {p: i for i, p in enumerate(PERMS)}
MUL = [[INDEX[tuple(p[q[v]] for v in range(N))] for q in PERMS]
       for p in PERMS]
TOTAL = len(PERMS)


def subgroup_generated(generators):
    """Return a bitmask of the subgroup generated by permutations."""
    seen = {0}
    todo = [0]
    while todo:
        a = todo.pop()
        for b in generators:
            c = MUL[a][b]
            if c not in seen:
                seen.add(c)
                todo.append(c)
    return sum(1 << i for i in seen)


def subgroups_of_s5():
    observed = {1}
    todo = [1]
    while todo:
        group = todo.pop()
        generators = [i for i in range(TOTAL) if (group >> i) & 1]
        for k in range(1, TOTAL):
            if (group >> k) & 1:
                continue
            enlarged = subgroup_generated(generators + [k])
            if enlarged not in observed:
                observed.add(enlarged)
                todo.append(enlarged)
    return observed


def orbitals(group):
    """Bitmasks of orbits on ordered pairs of vertex labels."""
    group_elements = [PERMS[k] for k in range(TOTAL) if (group >> k) & 1]
    unseen = set(range(N * N))
    parts = []
    while unseen:
        a, b = divmod(min(unseen), N)
        component = {N * p[a] + p[b] for p in group_elements}
        assert component <= unseen
        unseen -= component
        parts.append(sum(1 << v for v in component))
    return parts


def nonsingular(matrix_mask):
    """Exact row elimination in F_2, no floating point."""
    rows = [(matrix_mask >> (N * row)) & ((1 << N) - 1)
            for row in range(N)]
    for col in range(N):
        pivot = next((row for row in range(col, N)
                      if (rows[row] >> col) & 1), None)
        if pivot is None:
            return False
        rows[col], rows[pivot] = rows[pivot], rows[col]
        for row in range(col + 1, N):
            if (rows[row] >> col) & 1:
                rows[row] ^= rows[col]
    return True


def fixed_count(group):
    """All invertible matrices invariant under group conjugation."""
    components = orbitals(group)
    if len(components) == N * N:
        return prod(2**N - 2**i for i in range(N))
    mask = 0
    out = 0
    for k in range(1 << len(components)):
        out += nonsingular(mask)
        if k + 1 < (1 << len(components)):
            flipped = ((k + 1) & -(k + 1)).bit_length() - 1
            mask ^= components[flipped]
    return out


def permutation_order(i):
    k = i
    count = 1
    while k != 0:
        k = MUL[k][i]
        count += 1
    return count


def group_type(group):
    order_counts = Counter(permutation_order(i) for i in range(TOTAL)
                           if (group >> i) & 1)
    order = group.bit_count()
    spec = tuple(sorted(order_counts.items()))
    # These signatures distinguish every subgroup isomorphism type
    # of S_5 with a nonempty exact-stabilizer fiber.
    identified = {
        (1, ((1, 1),)): '1',
        (2, ((1, 1), (2, 1))): 'C2',
        (3, ((1, 1), (3, 2))): 'C3',
        (4, ((1, 1), (2, 1), (4, 2))): 'C4',
        (4, ((1, 1), (2, 3))): 'V4',
        (5, ((1, 1), (5, 4))): 'C5',
        (6, ((1, 1), (2, 1), (3, 2), (6, 2))): 'C6',
        (6, ((1, 1), (2, 3), (3, 2))): 'S3',
        (8, ((1, 1), (2, 5), (4, 2))): 'D8',
        (10, ((1, 1), (2, 5), (5, 4))): 'D10',
        (12, ((1, 1), (2, 3), (3, 8))): 'A4',
        (12, ((1, 1), (2, 7), (3, 2), (6, 2))): 'D12',
        (20, ((1, 1), (2, 5), (4, 10), (5, 4))): 'F20',
        (24, ((1, 1), (2, 9), (3, 8), (4, 6))): 'S4',
        (60, ((1, 1), (2, 15), (3, 20), (5, 24))): 'A5',
        (120, ((1, 1), (2, 25), (3, 20), (4, 30), (5, 24), (6, 20))): 'S5',
    }
    return identified[order, spec]


def verify_small_n():
    # Directly count orbit representatives among invertible 3x3 and 4x4
    # binary matrices using a separate, brute-force action implementation.
    for n, expected in [(3, 33), (4, 908)]:
        all_perms = list(permutations(range(n)))
        row_mask = (1 << n) - 1
        def is_unit(a):
            rows = [(a >> (n * i)) & row_mask for i in range(n)]
            for c in range(n):
                pivot = next((i for i in range(c, n) if (rows[i] >> c) & 1), None)
                if pivot is None:
                    return False
                rows[c], rows[pivot] = rows[pivot], rows[c]
                for i in range(c + 1, n):
                    if (rows[i] >> c) & 1:
                        rows[i] ^= rows[c]
            return True
        fixed_sum = 0
        for a in range(1 << (n * n)):
            if not is_unit(a):
                continue
            for p in all_perms:
                if all(((a >> (n * i + j)) & 1) ==
                       ((a >> (n * p[i] + p[j])) & 1)
                       for i in range(n) for j in range(n)):
                    fixed_sum += 1
        assert fixed_sum // len(all_perms) == expected
        assert fixed_sum % len(all_perms) == 0


def main():
    groups = subgroups_of_s5()
    assert len(groups) == 156
    fixed = {h: fixed_count(h) for h in groups}
    assert fixed[1] == 9_999_360
    # Independent Burnside sum from the rational-canonical types of 5x5
    # permutation matrices: (type, class size, invertible commutant size).
    cycle_data = [
        ('1^5', 1, 9_999_360),
        ('2,1^3', 10, 21_504),
        ('2^2,1', 15, 1_536),
        ('3,1^2', 20, 504),
        ('3,2', 20, 24),
        ('4,1', 30, 32),
        ('5', 24, 15),
    ]
    assert sum(k for _, k, _ in cycle_data) == 120
    assert sum(k * count for _, k, count in cycle_data) == 10_249_320
    # Check independent module-centralizer fixed counts for every element.
    def cycle_lengths(p):
        unseen = set(range(N)); lengths = []
        while unseen:
            v = min(unseen); w = v; cycle = []
            while w not in cycle:
                cycle.append(w); w = p[w]
            unseen.difference_update(cycle)
            lengths.append(len(cycle))
        return tuple(sorted(lengths, reverse=True))
    expected_fix = {
        (1,1,1,1,1): 9_999_360,
        (2,1,1,1): 21_504,
        (2,2,1): 1_536,
        (3,1,1): 504,
        (3,2): 24,
        (4,1): 32,
        (5,): 15,
    }
    for i, p in enumerate(PERMS):
        assert fixed[subgroup_generated([i])] == expected_fix[cycle_lengths(p)]
    assert sum(fixed[subgroup_generated([i])] for i in range(TOTAL)) == 10_249_320
    # Superset inversion in the finite subgroup poset.
    exact = {}
    for h in sorted(groups, key=int.bit_count, reverse=True):
        exact[h] = fixed[h] - sum(exact[k] for k in exact if h & k == h)
        assert exact[h] >= 0
    assert sum(exact.values()) == fixed[1]
    labeled_by_group = Counter()
    for h, count in exact.items():
        labeled_by_group[group_type(h)] += count
    order_map = {'1':1,'C2':2,'C3':3,'C4':4,'V4':4,'C5':5,
                 'C6':6,'S3':6,'D8':8,'D10':10,'A4':12,'D12':12,
                 'F20':20,'S4':24,'A5':60,'S5':120}
    expected_orbits = {'1':81408,'C2':3694,'C3':80,'C4':8,'V4':113,
                       'C5':3,'C6':8,'S3':73,'D8':8,'D10':1,
                       'A4':0,'D12':7,'F20':0,'S4':7,'A5':0,'S5':1}
    assert set(labeled_by_group) == set(expected_orbits)
    orbit_total = 0
    for name, wanted in expected_orbits.items():
        labeled = labeled_by_group[name]
        order = order_map[name]
        assert labeled * order % 120 == 0
        calculated = labeled * order // 120
        assert calculated == wanted, (name, calculated, wanted)
        orbit_total += calculated
    assert orbit_total == 85_411 == 10_249_320 // 120
    verify_small_n()
    print('VERIFY_OK: 156 S5 subgroups; 9,999,360 invertible binary matrices;'
          ' 85,411 orbit classes; complete 16-type spectrum;'
          ' small-dimension direct Burnside cross-checks')
    for name, number in expected_orbits.items():
        print(name, number)

if __name__ == '__main__':
    main()
